import Foundation
import CryptoKit

// MARK: - Encrypted Storage Layer
struct EncryptedField {
    let ciphertext: Data
    let nonce: AES.GCM.Nonce
    let tag: Data

    func decrypt(with key: SymmetricKey) throws -> String {
        let sealedBox = try AES.GCM.SealedBox(nonce: nonce, ciphertext: ciphertext, tag: tag)
        let decrypted = try AES.GCM.open(sealedBox, using: key)
        return String(data: decrypted, encoding: .utf8) ?? ""
    }
}

// MARK: - Smart Contract State
class ContractStorage {
    private var storageKey: SymmetricKey
    private var balances: [String: EncryptedField] = [:]
    private var queryLog: [String] = []

    init(masterKey: Data) {
        self.storageKey = SymmetricKey(data: masterKey)
    }

    func encryptValue(_ value: String) throws -> EncryptedField {
        let data = value.data(using: .utf8)!
        let nonce = AES.GCM.Nonce()
        let sealed = try AES.GCM.seal(data, using: storageKey, nonce: nonce)
        return EncryptedField(ciphertext: sealed.ciphertext, nonce: nonce, tag: sealed.tag)
    }

    func setBalance(address: String, amount: String) throws {
        balances[address] = try encryptValue(amount)
    }

    func getBalance(address: String) throws -> String? {
        guard let field = balances[address] else { return nil }
        return try field.decrypt(with: storageKey)
    }
}

// MARK: - GraphQL Query Resolution
struct GraphQLResolver {
    let storage: ContractStorage

    // Introspection depth tracking for nested query protection
    private let maxDepth = 5

    struct QueryContext {
        var depth: Int = 0
        var fragments: [String: String] = [:]
        var variables: [String: Any] = [:]
    }

    func resolveQuery(_ rawQuery: String, variables: [String: Any] = [:]) throws -> [String: Any] {
        var context = QueryContext()
        context.variables = variables
        return try parseAndExecute(rawQuery, context: &context)
    }

    private func parseAndExecute(_ query: String, context: inout QueryContext) throws -> [String: Any] {
        context.depth += 1
        guard context.depth <= maxDepth else {
            return ["error": "Query depth exceeded"]
        }

        // Extract operation from query
        let normalized = normalizeQuery(query)

        if normalized.contains("balanceOf") {
            return try resolveBalanceOf(normalized, context: &context)
        } else if normalized.contains("__schema") || normalized.contains("__type") {
            return resolveIntrospection(normalized)
        }

        return ["error": "Unknown query"]
    }

    private func normalizeQuery(_ query: String) -> String {
        // Remove comments and normalize whitespace
        let lines = query.components(separatedBy: "\n")
        let filtered = lines.filter { !$0.trimmingCharacters(in: .whitespaces).hasPrefix("#") }
        return filtered.joined(separator: " ")
            .replacingOccurrences(of: "\t", with: " ")
            .replacingOccurrences(of: "  ", with: " ")
    }

    private func resolveBalanceOf(_ query: String, context: inout QueryContext) throws -> [String: Any] {
        // Extract address argument using field resolution
        guard let address = extractArgument(query, field: "balanceOf", arg: "address") else {
            return ["error": "Missing address argument"]
        }

        // Build the storage lookup key - validate before resolution
        let resolvedAddress = resolveVariables(address, context: context)

        // Validate resolved address is a proper hex address
        guard isValidAddress(resolvedAddress) else {
            return ["error": "Invalid address format"]
        }

        guard let balance = try storage.getBalance(address: resolvedAddress) else {
            return ["data": ["balanceOf": NSNull()]]
        }

        return ["data": ["balanceOf": balance]]
    }

    private func isValidAddress(_ address: String) -> Bool {
        // Only allow hex addresses: 0x followed by exactly 40 hex chars
        let pattern = "^0x[0-9a-fA-F]{40}$"
        return address.range(of: pattern, options: .regularExpression) != nil
    }

    private func extractArgument(_ query: String, field: String, arg: String) -> String? {
        // Find field(arg: "value") or field(arg: $var) pattern
        guard let fieldRange = query.range(of: field) else { return nil }
        let afterField = String(query[fieldRange.upperBound...])

        guard let parenStart = afterField.firstIndex(of: "(") else { return nil }
        guard let parenEnd = afterField.firstIndex(of: ")") else { return nil }

        let argsStr = String(afterField[afterField.index(after: parenStart)..<parenEnd])

        // Parse arg: "value" or arg: $variable
        let argPattern = "\(arg):"
        guard let argStart = argsStr.range(of: argPattern) else { return nil }
        let valueStr = String(argsStr[argStart.upperBound...]).trimmingCharacters(in: .whitespaces)

        if valueStr.hasPrefix("\"") {
            // String literal - extract between quotes
            let inner = String(valueStr.dropFirst())
            if let endQuote = inner.firstIndex(of: "\"") {
                return String(inner[..<endQuote])
            }
        } else if valueStr.hasPrefix("$") {
            // Variable reference
            let varName = String(valueStr.dropFirst()).components(separatedBy: CharacterSet.alphanumerics.inverted).first ?? ""
            return "$\(varName)"
        }

        return nil
    }

    private func resolveVariables(_ input: String, context: QueryContext) -> String {
        if input.hasPrefix("$") {
            let varName = String(input.dropFirst())
            if let value = context.variables[varName] as? String {
                return value
            }
            return ""
        }
        return input
    }

    private func resolveIntrospection(_ query: String) -> [String: Any] {
        return ["data": ["__schema": ["types": ["Contract", "Query"]]]]
    }
}

// MARK: - Contract Entry Point (HTTP Handler)
func handleGraphQLRequest(body: Data, storage: ContractStorage) -> Data {
    do {
        guard let json = try JSONSerialization.jsonObject(with: body) as? [String: Any],
              let query = json["query"] as? String else {
            return errorResponse("Invalid request body")
        }

        let variables = json["variables"] as? [String: Any] ?? [:]
        let resolver = GraphQLResolver(storage: storage)
        let result = try resolver.resolveQuery(query, variables: variables)

        return try JSONSerialization.data(withJSONObject: result)
    } catch {
        return errorResponse("Internal error")
    }
}

func errorResponse(_ message: String) -> Data {
    let response: [String: Any] = ["errors": [["message": message]]]
    return (try? JSONSerialization.data(withJSONObject: response)) ?? Data()
}
